"use client";

import Image from "next/image";
import Script from "next/script";
import { useRouter } from "next/navigation";
import { useState, useTransition } from "react";
import { CreditCard, Lock, Wallet } from "lucide-react";
import { previewQuote, reportPaymentFailure, startCheckout, verifyPayment } from "@/app/actions/checkout";
import { formatINR } from "@/lib/money";
import { cn } from "@/lib/utils";

const STATES = [
  "Tamil Nadu", "Puducherry", "Kerala", "Karnataka", "Andhra Pradesh", "Telangana", "Maharashtra", "Goa", "Gujarat", "Delhi",
  "Rajasthan", "Punjab", "Haryana", "Uttar Pradesh", "Uttarakhand", "Himachal Pradesh", "Jammu and Kashmir", "Ladakh",
  "Madhya Pradesh", "Chhattisgarh", "Bihar", "Jharkhand", "Odisha", "West Bengal", "Sikkim", "Assam", "Arunachal Pradesh",
  "Nagaland", "Manipur", "Mizoram", "Tripura", "Meghalaya", "Chandigarh", "Andaman and Nicobar Islands",
  "Dadra and Nagar Haveli and Daman and Diu", "Lakshadweep",
];

type Address = { id: string; name: string; phone: string; line1: string; line2: string | null; city: string; state: string; pincode: string };
type Line = { id: string; name: string; image: string | null; quantity: number; price: number; engravingText: string };
type Totals = { subtotal: number; discount: number; shippingFee: number; taxTotal: number; total: number };

type RazorpayResponse = { razorpay_order_id: string; razorpay_payment_id: string; razorpay_signature: string };
type RazorpayInstance = { open: () => void; on: (event: string, cb: (r: { error: { description: string; metadata?: { order_id?: string } } }) => void) => void };
declare global {
  interface Window {
    Razorpay?: new (options: Record<string, unknown>) => RazorpayInstance;
  }
}

export function CheckoutForm(props: {
  user: { name: string; email: string; phone: string | null };
  addresses: Address[];
  lines: Line[];
  totals: Totals;
  emiAvailable: boolean;
}) {
  const router = useRouter();
  const def = props.addresses.find((a) => a) ?? null;
  const [selected, setSelected] = useState<string>(def?.id ?? "new");
  const [addr, setAddr] = useState({ name: props.user.name, phone: props.user.phone ?? "", line1: "", line2: "", city: "", state: "Tamil Nadu", pincode: "" });
  const [saveAddress, setSaveAddress] = useState(true);
  const [email, setEmail] = useState(props.user.email);
  const [notes, setNotes] = useState("");
  const [coupon, setCoupon] = useState("");
  const [applied, setApplied] = useState<string | null>(null);
  const [totals, setTotals] = useState<Totals>(props.totals);
  const [couponMsg, setCouponMsg] = useState<string | null>(null);
  const [payMode, setPayMode] = useState<"full" | "emi">("full");
  const [error, setError] = useState<string | null>(null);
  const [status, setStatus] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const [sdkReady, setSdkReady] = useState(false);

  const applyCoupon = (code: string | null) =>
    start(async () => {
      const q = await previewQuote(code);
      setTotals(q);
      setApplied(q.coupon);
      setCouponMsg(code ? q.couponError ?? `Coupon ${q.coupon} applied — you save ${formatINR(q.discount)}` : null);
    });

  const chosenAddress = () => {
    if (selected === "new") return addr;
    const a = props.addresses.find((x) => x.id === selected)!;
    return { name: a.name, phone: a.phone, line1: a.line1, line2: a.line2 ?? "", city: a.city, state: a.state, pincode: a.pincode };
  };

  const pay = () =>
    start(async () => {
      setError(null);
      if (!sdkReady || !window.Razorpay) return setError("Payment module is still loading. Please try again in a moment.");
      const res = await startCheckout({
        email,
        address: chosenAddress(),
        couponCode: applied,
        preferEmi: payMode === "emi",
        notes,
        saveAddress: selected === "new" && saveAddress,
      });
      if (!res.ok) return setError(res.error);

      const emiBlock = {
        display: {
          blocks: {
            emi: {
              name: "Pay in easy EMIs",
              instruments: [{ method: "emi" }, { method: "cardless_emi" }, { method: "paylater" }],
            },
          },
          sequence: ["block.emi"],
          preferences: { show_default_blocks: true },
        },
      };

      const rzp = new window.Razorpay({
        key: res.keyId,
        amount: res.amount,
        currency: "INR",
        name: "Sun Metals Store",
        description: `Order ${res.orderNumber}`,
        image: `${window.location.origin}/logo.png`,
        order_id: res.razorpayOrderId,
        prefill: res.prefill,
        notes: { orderNumber: res.orderNumber },
        theme: { color: "#8b1e1e" },
        retry: { enabled: true, max_count: 3 },
        ...(res.preferEmi ? { config: emiBlock } : {}),
        modal: {
          confirm_close: true,
          ondismiss: () => {
            setStatus(null);
            setError("Payment was not completed. Your cart is saved — you can try again.");
          },
        },
        handler: async (response: RazorpayResponse) => {
          setStatus("Confirming your payment…");
          const v = await verifyPayment(response);
          if (v.ok) router.replace(`/order/${v.orderNumber}?placed=1`);
          else {
            setStatus(null);
            setError(v.error);
          }
        },
      });
      rzp.on("payment.failed", (r) => {
        void reportPaymentFailure(res.razorpayOrderId, r.error?.description ?? "failed");
      });
      rzp.open();
    });

  const field = (k: keyof typeof addr, label: string, extra: React.InputHTMLAttributes<HTMLInputElement> = {}) => (
    <div>
      <label className="label" htmlFor={`a-${k}`}>{label}</label>
      <input id={`a-${k}`} className="input" value={addr[k]} onChange={(e) => setAddr({ ...addr, [k]: e.target.value })} {...extra} />
    </div>
  );

  return (
    <div className="grid gap-6 lg:grid-cols-[1fr_360px]">
      <Script src="https://checkout.razorpay.com/v1/checkout.js" strategy="afterInteractive" onReady={() => setSdkReady(true)} />
      <div className="space-y-6">
        <section className="card p-5">
          <h2 className="mb-4 font-display text-xl font-semibold">1. Delivery address</h2>
          <div className="space-y-2">
            {props.addresses.map((a) => (
              <label key={a.id} className={cn("flex cursor-pointer gap-3 rounded-md border p-3 text-sm", selected === a.id ? "border-brass bg-brass-light/40" : "border-line")}>
                <input type="radio" name="addr" checked={selected === a.id} onChange={() => setSelected(a.id)} className="mt-1 accent-brass" />
                <span><span className="font-semibold">{a.name}</span>, {a.line1}{a.line2 && `, ${a.line2}`}, {a.city}, {a.state} – {a.pincode} · {a.phone}</span>
              </label>
            ))}
            {props.addresses.length > 0 && (
              <label className={cn("flex cursor-pointer gap-3 rounded-md border p-3 text-sm", selected === "new" ? "border-brass bg-brass-light/40" : "border-line")}>
                <input type="radio" name="addr" checked={selected === "new"} onChange={() => setSelected("new")} className="accent-brass" />
                <span className="font-semibold">Add a new address</span>
              </label>
            )}
          </div>
          {selected === "new" && (
            <div className="mt-4 grid gap-3 sm:grid-cols-2">
              {field("name", "Full name", { autoComplete: "name", required: true })}
              {field("phone", "Mobile number", { autoComplete: "tel", inputMode: "tel", required: true })}
              <div className="sm:col-span-2">{field("line1", "Flat, house no., building, street", { autoComplete: "address-line1", required: true })}</div>
              <div className="sm:col-span-2">{field("line2", "Area, landmark (optional)", { autoComplete: "address-line2" })}</div>
              {field("city", "Town / City", { autoComplete: "address-level2", required: true })}
              {field("pincode", "PIN code", { autoComplete: "postal-code", inputMode: "numeric", maxLength: 6, required: true })}
              <div className="sm:col-span-2">
                <label className="label" htmlFor="a-state">State</label>
                <select id="a-state" className="input" value={addr.state} onChange={(e) => setAddr({ ...addr, state: e.target.value })}>
                  {STATES.map((s) => <option key={s}>{s}</option>)}
                </select>
              </div>
              <label className="flex items-center gap-2 text-sm sm:col-span-2">
                <input type="checkbox" checked={saveAddress} onChange={(e) => setSaveAddress(e.target.checked)} className="accent-brass" /> Save this address for next time
              </label>
            </div>
          )}
          <div className="mt-4 grid gap-3 sm:grid-cols-2">
            <div>
              <label className="label" htmlFor="email">Email for order updates</label>
              <input id="email" type="email" className="input" value={email} onChange={(e) => setEmail(e.target.value)} autoComplete="email" />
            </div>
            <div>
              <label className="label" htmlFor="notes">Delivery notes (optional)</label>
              <input id="notes" className="input" value={notes} onChange={(e) => setNotes(e.target.value)} maxLength={500} />
            </div>
          </div>
        </section>

        <section className="card p-5">
          <h2 className="mb-4 font-display text-xl font-semibold">2. Payment method</h2>
          <div className="grid gap-3 sm:grid-cols-2">
            <button type="button" onClick={() => setPayMode("full")} className={cn("flex gap-3 rounded-md border p-4 text-left", payMode === "full" ? "border-brass bg-brass-light/40" : "border-line")}>
              <Wallet className="h-6 w-6 shrink-0 text-brass" aria-hidden />
              <span><span className="block font-semibold">Pay in full</span><span className="text-xs text-muted">UPI (GPay, PhonePe, Paytm), cards, net banking, wallets</span></span>
            </button>
            <button type="button" disabled={!props.emiAvailable} onClick={() => setPayMode("emi")} className={cn("flex gap-3 rounded-md border p-4 text-left disabled:opacity-50", payMode === "emi" ? "border-brass bg-brass-light/40" : "border-line")}>
              <CreditCard className="h-6 w-6 shrink-0 text-brass" aria-hidden />
              <span>
                <span className="block font-semibold">Pay with EMI</span>
                <span className="text-xs text-muted">{props.emiAvailable ? "Credit/debit card EMI, Bajaj Finserv EMI Card, cardless EMI & pay-later" : "Available on eligible orders above ₹3,000"}</span>
              </span>
            </button>
          </div>
          <p className="mt-3 flex items-center gap-1.5 text-xs text-muted"><Lock className="h-3.5 w-3.5" aria-hidden /> You will complete payment securely in the Razorpay window. We never see or store your card details.</p>
        </section>

        <section className="card p-5">
          <h2 className="mb-4 font-display text-xl font-semibold">3. Review items</h2>
          <ul className="divide-y divide-line">
            {props.lines.map((l) => (
              <li key={l.id} className="flex items-center gap-3 py-3 text-sm">
                <div className="relative h-14 w-14 shrink-0 rounded bg-paper">{l.image && <Image src={l.image} alt="" fill sizes="56px" className="object-contain p-1" />}</div>
                <div className="flex-1"><p className="font-medium">{l.name}</p>{l.engravingText && <p className="text-xs text-brass">Engraving: “{l.engravingText}”</p>}<p className="text-xs text-muted">Qty {l.quantity}</p></div>
                <p className="font-semibold">{formatINR(l.price * l.quantity)}</p>
              </li>
            ))}
          </ul>
        </section>
      </div>

      <aside className="card h-fit space-y-4 p-5 lg:sticky lg:top-36">
        <button onClick={pay} disabled={pending || !!status} className="btn-brass w-full rounded-full py-3 text-base">
          {status ?? (pending ? "Please wait…" : payMode === "emi" ? "Continue to EMI payment" : "Place order & pay")}
        </button>
        {error && <p role="alert" className="rounded-md bg-danger/10 p-3 text-sm text-danger">{error}</p>}
        <div className="flex gap-2">
          <input value={coupon} onChange={(e) => setCoupon(e.target.value.toUpperCase())} placeholder="Coupon code" className="input" maxLength={40} aria-label="Coupon code" />
          {applied ? (
            <button type="button" onClick={() => { setCoupon(""); applyCoupon(null); }} className="btn-outline">Remove</button>
          ) : (
            <button type="button" disabled={!coupon || pending} onClick={() => applyCoupon(coupon)} className="btn-outline">Apply</button>
          )}
        </div>
        {couponMsg && <p className={cn("text-xs", applied ? "text-success" : "text-danger")}>{couponMsg}</p>}
        <dl className="space-y-1.5 border-t border-line pt-3 text-sm">
          <div className="flex justify-between"><dt>Items</dt><dd>{formatINR(totals.subtotal)}</dd></div>
          {totals.discount > 0 && <div className="flex justify-between text-success"><dt>Coupon discount</dt><dd>−{formatINR(totals.discount)}</dd></div>}
          <div className="flex justify-between"><dt>Delivery</dt><dd>{totals.shippingFee ? formatINR(totals.shippingFee) : <span className="text-success">FREE</span>}</dd></div>
          <div className="flex justify-between border-t border-line pt-2 text-lg font-semibold text-maroon"><dt>Order total</dt><dd>{formatINR(totals.total)}</dd></div>
          <p className="text-xs text-muted">Includes GST of {formatINR(totals.taxTotal, true)}</p>
        </dl>
      </aside>
    </div>
  );
}
